      { prompt: "Why is “hace tres días” important in Alex’s symptom sentence?", choices: ["It says the symptom is imaginary.", "It names the medicine dosage.", "It gives duration that continues now."], answer: 2, tests: "hace plus time with ongoing symptoms" },
      { prompt: "If Alex needs proof for work, what word should he know?", choices: ["incapacidad", "parche", "taxímetro"], answer: 0, tests: "Colombian medical leave terminology" },
      { prompt: "The doctor mentions “la fórmula médica.” What is she talking about?", choices: ["A blood test appointment.", "A prescription for medication.", "A payment at reception."], answer: 1, tests: "fórmula médica as prescription" }
