      { prompt: "Why does Alex say “Queda pendiente la aprobación” rather than “Laura no aprobó”?", choices: ["It makes the update sound more cheerful than accurate.", "It reports the blocker without publicly assigning blame.", "It means Laura has already approved the report."], answer: 1, tests: "impersonal framing for delays" },
      { prompt: "What does “quedaría listo el jueves” signal in the update?", choices: ["The report was definitely finished last Thursday.", "The date is impossible unless Laura rewrites it.", "The date is likely, but still hedged by conditions."], answer: 2, tests: "conditional hedging in status reports" },
      { prompt: "In a Colombian office, what does “le hago seguimiento” most likely show?", choices: ["A warm professional usted, not emotional distance.", "A cold refusal to work with a teammate.", "A regional vos form from Antioquia or Valle."], answer: 0, tests: "usted as collegial workplace register" }
